New task:
TASK AND SPECIFICATIONS
{
  "schema_version": 1,
  "id": "SELF003",
  "kind": "self_built",
  "title": "Emergency stop reset with restart inhibition",
  "difficulty": "medium",
  "provenance": {
    "source_type": "independent_synthesis",
    "source_file": "scripts/build_self_dataset.py",
    "source_index": 3,
    "adaptation": "Independently specified for this project; no public task was copied. The coding assistant chose the state variables, priority order and fixed scan traces, then reviewed the traces against a separate Python transition implementation.",
    "rationale": "A workshop spindle requires a deliberate reset with Start released before a restart after emergency-stop release.",
    "review": "Assistant consistency review of initialization, simultaneous commands, retained state and recovery boundaries; independent Python oracle checked against manual expected traces. Not an industrial safety certification or external expert review."
  },
  "requirements": "Run initially is FALSE and ResetRequired initially is TRUE. EStopNC=FALSE immediately forces Run FALSE and sets ResetRequired TRUE. While ResetRequired is TRUE, keep Run FALSE. Clear ResetRequired only when EStopNC is TRUE, Reset is TRUE, Start is FALSE and Stop is FALSE. That clearing scan cannot start the motor. Once reset, Stop stops the motor, Start starts it, otherwise retain Run. Start held during reset must not clear the restart inhibition. This educational logic does not implement a certified emergency-stop chain.",
  "scenario": "A workshop spindle requires a deliberate reset with Start released before a restart after emergency-stop release.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "Start",
      "type": "BOOL",
      "description": "Start request"
    },
    {
      "direction": "INPUT",
      "name": "Stop",
      "type": "BOOL",
      "description": "Normal stop request"
    },
    {
      "direction": "INPUT",
      "name": "EStopNC",
      "type": "BOOL",
      "description": "TRUE means emergency stop released"
    },
    {
      "direction": "INPUT",
      "name": "Reset",
      "type": "BOOL",
      "description": "Reset request"
    },
    {
      "direction": "OUTPUT",
      "name": "Run",
      "type": "BOOL",
      "description": "Spindle run command"
    },
    {
      "direction": "OUTPUT",
      "name": "ResetRequired",
      "type": "BOOL",
      "description": "Restart inhibition latch"
    }
  ],
  "initial_conditions": {
    "Run": false,
    "ResetRequired": true
  },
  "scan_semantics": "At scan k, sample every input once, read retained pre-state q[k], execute one transition, and observe outputs O[k] at the end of that same scan. Updated state becomes q[k+1]. Reset the instance before each test. Step 0 executes normally; initial conditions describe pre-state, not an extra delayed scan. All timing in this task is explicitly counted in invocations, not wall time.",
  "safety_priority": [
    "Emergency stop overrides all requests",
    "Restart inhibition overrides Start",
    "Normal stop overrides Start"
  ],
  "assumptions": [],
  "atomic_propositions": {
    "Start": "Start request Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Stop": "Normal stop request Boolean names are propositions; numeric names appear only inside defined predicates.",
    "EStopNC": "TRUE means emergency stop released Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Reset": "Reset request Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Run": "Spindle run command Boolean names are propositions; numeric names appear only inside defined predicates.",
    "ResetRequired": "Restart inhibition latch Boolean names are propositions; numeric names appear only inside defined predicates.",
    "first": "True only on the first invocation after resetting the FB instance.",
    "qRequired": "Pre-scan ResetRequired, initially TRUE.",
    "qRun": "Pre-scan Run, initially FALSE.",
    "validReset": "EStopNC & Reset & !Start & !Stop."
  },
  "ltl": [
    {
      "id": "P1",
      "formula": "G(first -> (qRequired & !qRun))",
      "explanation": "A fresh instance requires reset."
    },
    {
      "id": "P2",
      "formula": "G(!EStopNC -> (!Run & ResetRequired))",
      "explanation": "Emergency stop forces safe outputs immediately."
    },
    {
      "id": "P3",
      "formula": "G(qRequired -> !Run)",
      "explanation": "Reset acceptance and motor start cannot share one scan."
    },
    {
      "id": "P4",
      "formula": "G((qRequired & EStopNC) -> (ResetRequired <-> !validReset))",
      "explanation": "Reset requires released Start and Stop."
    },
    {
      "id": "P5",
      "formula": "G((!qRequired & EStopNC & !Stop & Start) -> Run)",
      "explanation": "A subsequent permitted start energizes the motor."
    },
    {
      "id": "P6",
      "formula": "G((!qRequired & EStopNC & Stop) -> !Run)",
      "explanation": "Stop has priority after reset."
    }
  ],
  "tests": [
    {
      "id": "reset_restart",
      "purpose": "Power-up inhibition, reset, run and emergency stop",
      "steps": [
        {
          "inputs": {
            "Start": true,
            "Stop": false,
            "EStopNC": true,
            "Reset": false
          },
          "expected": {
            "Run": false,
            "ResetRequired": true
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "EStopNC": true,
            "Reset": true
          },
          "expected": {
            "Run": false,
            "ResetRequired": false
          }
        },
        {
          "inputs": {
            "Start": true,
            "Stop": false,
            "EStopNC": true,
            "Reset": false
          },
          "expected": {
            "Run": true,
            "ResetRequired": false
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "EStopNC": true,
            "Reset": false
          },
          "expected": {
            "Run": true,
            "ResetRequired": false
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "EStopNC": false,
            "Reset": true
          },
          "expected": {
            "Run": false,
            "ResetRequired": true
          }
        },
        {
          "inputs": {
            "Start": true,
            "Stop": false,
            "EStopNC": true,
            "Reset": false
          },
          "expected": {
            "Run": false,
            "ResetRequired": true
          }
        }
      ]
    },
    {
      "id": "invalid_reset",
      "purpose": "Held Start and Stop block reset",
      "steps": [
        {
          "inputs": {
            "Start": true,
            "Stop": false,
            "EStopNC": true,
            "Reset": true
          },
          "expected": {
            "Run": false,
            "ResetRequired": true
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": true,
            "EStopNC": true,
            "Reset": true
          },
          "expected": {
            "Run": false,
            "ResetRequired": true
          }
        },
        {
          "inputs": {
            "Start": false,
            "Stop": false,
            "EStopNC": true,
            "Reset": true
          },
          "expected": {
            "Run": false,
            "ResetRequired": false
          }
        },
        {
          "inputs": {
            "Start": true,
            "Stop": true,
            "EStopNC": true,
            "Reset": true
          },
          "expected": {
            "Run": false,
            "ResetRequired": false
          }
        }
      ]
    }
  ]
}
